// Initialize DP table and parent pointers
dp[0][0] = 0;
for (let i = 1; i <= n; i++) {
  dp[i][1] = rangeMin(1, i) * prefix[i];
  parent[i][1] = 0;
}

// Fill DP table
for (let t = 2; t <= k; t++) {
  for (let i = t; i <= n; i++) {
    for (let p = t-1; p < i; p++) {
      const segVal = rangeMin(p+1, i) * (prefix[i] - prefix[p]);
      const total = dp[p][t-1] + segVal;
      if (total > dp[i][t]) {
        dp[i][t] = total;
        parent[i][t] = p;
      }
    }
  }
}

// Reconstruct segments
let i = n, t = k;
while (t > 0) {
  const p = parent[i][t];
  segments[t] = [p+1, i];
  i = p;
  t--;
}
```

